#[test]
fn suggest_conflict_values() {
    let mut cmd = Command::new("dynamic")
        .arg(
            clap::Arg::new("color")
                .long("color")
                .value_parser(["always", "auto", "never"]),
        )
        .arg(
            clap::Arg::new("plain")
                .long("plain")
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("color"),
